export const LOGIN_MESSAGE='Đăng nhập MUSE để tạo ảnh và video. Upscale 4K vẫn dùng độc lập.';
export const generationRequest=(url,method='POST')=>method==='POST'&&(/^\/api\/queue\/(preflight|enqueue|process|retry\/)/.test(url)||/^\/api\/(concept\/analyze|magnific\/generate|exact-video|prompt-assistant\/improve)/.test(url));
export function reportMuseLogin(){window.dispatchEvent(new Event('mopix-login-required'));return Error(LOGIN_MESSAGE)}
export async function requireMuseLogin(){let response=await fetch('/api/muse/session');let authenticated;if(response.status===404){response=await fetch('/api/accounts');if(!response.ok)throw Error('Không kiểm tra được phiên MUSE. Thử lại.');const rows=await response.json();authenticated=rows.some(a=>a.enabled&&a.status==='online')}else{if(!response.ok)throw Error('Không kiểm tra được phiên MUSE. Thử lại.');authenticated=(await response.json()).authenticated}if(!authenticated)throw reportMuseLogin()}
export function createMuseLoginNotice(React){const{createElement:h,useState:S,useEffect:E,useRef:R}=React;return function Notice({onNavigate}){const[open,O]=S(false),modal=R(null);E(()=>{const show=()=>O(true);window.addEventListener('mopix-login-required',show);return()=>window.removeEventListener('mopix-login-required',show)},[]);E(()=>{if(open)modal.current?.showModal()},[open]);return open&&h('dialog',{ref:modal,className:'mopix-options-modal mopix-login-dialog','aria-label':'Đăng nhập MUSE',onCancel:()=>O(false),onClick:e=>{if(e.target===e.currentTarget)O(false)}},h('section',null,h('header',null,h('h2',null,'Kết nối MUSE'),h('button',{type:'button','aria-label':'Đóng yêu cầu đăng nhập',onClick:()=>O(false)},'×')),h('p',null,LOGIN_MESSAGE),h('footer',null,h('button',{type:'button',onClick:()=>{O(false);sessionStorage.setItem('mopix-login-intent','accounts');onNavigate('settings')}},'Đăng nhập MUSE'))))}}
